/* ── Reset & Tokens ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-base:     #0d0d0f;
  --bg-surface:  #141416;
  --bg-card:     #1a1a1e;
  --bg-card-alt: #1f1f24;
  --border:      #2a2a30;
  --border-light:#3a3a44;
  --accent:      #e8c97a;
  --accent-dim:  #c9a84c;
  --accent-glow: rgba(232,201,122,.15);
  --red:         #e05252;
  --green:       #52d98a;
  --text-primary:#f0eff4;
  --text-secondary:#9e9eac;
  --text-muted:  #5a5a68;
  --radius-sm:   6px;
  --radius-md:   12px;
  --radius-lg:   20px;
  --font:        'Inter', system-ui, sans-serif;
  --transition:  0.22s ease;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg-base);
  color: var(--text-primary);
  font-family: var(--font);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }

/* ── Utility ── */
.container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
.section-label {
  font-size: 11px; font-weight: 600; letter-spacing: .14em;
  text-transform: uppercase; color: var(--accent); margin-bottom: 8px;
}
.section-title {
  font-size: clamp(22px, 3vw, 32px); font-weight: 700;
  color: var(--text-primary); line-height: 1.25;
}
.section-header {
  display: flex; align-items: flex-end; justify-content: space-between;
  margin-bottom: 32px; gap: 16px; flex-wrap: wrap;
}
.see-all {
  font-size: 13px; font-weight: 500; color: var(--accent);
  border: 1px solid var(--border-light); border-radius: 99px;
  padding: 6px 18px; transition: background var(--transition), border-color var(--transition);
  white-space: nowrap;
}
.see-all:hover { background: var(--accent-glow); border-color: var(--accent); }

/* ── Navbar ── */
#navbar {
  position: sticky; top: 0; z-index: 100;
  background: rgba(13,13,15,.85);
  backdrop-filter: blur(18px) saturate(1.4);
  border-bottom: 1px solid var(--border);
}
.nav-inner {
  display: flex; align-items: center; gap: 0; height: 60px;
}
.nav-logo {
  font-size: 20px; font-weight: 800; letter-spacing: -.03em;
  color: var(--text-primary); margin-right: auto;
}
.nav-logo span { color: var(--accent); }
.nav-links {
  display: flex; gap: 2px; list-style: none;
}
.nav-links a {
  font-size: 13.5px; font-weight: 500; color: var(--text-secondary);
  padding: 8px 14px; border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover { color: var(--text-primary); background: var(--bg-card); }
.nav-actions {
  display: flex; align-items: center; gap: 6px; margin-left: 20px;
}
.nav-icon-btn {
  width: 38px; height: 38px; display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-sm); color: var(--text-secondary);
  transition: background var(--transition), color var(--transition);
  position: relative;
}
.nav-icon-btn:hover { background: var(--bg-card); color: var(--text-primary); }
.badge {
  position: absolute; top: 5px; right: 5px;
  width: 16px; height: 16px; border-radius: 50%;
  background: var(--accent); color: var(--bg-base);
  font-size: 9px; font-weight: 700; display: flex; align-items: center; justify-content: center;
  border: 2px solid var(--bg-base);
}
.nav-search {
  display: flex; align-items: center; gap: 8px;
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-sm); padding: 6px 14px;
  margin-left: 8px; width: 220px; transition: border-color var(--transition), width var(--transition);
}
.nav-search:focus-within { border-color: var(--accent); width: 260px; }
.nav-search input {
  background: none; border: none; outline: none;
  font-size: 13px; color: var(--text-primary); width: 100%;
}
.nav-search input::placeholder { color: var(--text-muted); }

/* ── Hero ── */
#hero {
  min-height: 86vh; display: flex; align-items: center;
  position: relative; overflow: hidden;
}
.hero-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 70% 60% at 65% 50%, rgba(232,201,122,.07) 0%, transparent 70%),
    radial-gradient(ellipse 50% 80% at 10% 90%, rgba(82,217,138,.05) 0%, transparent 60%),
    linear-gradient(160deg, #0d0d0f 0%, #11111a 100%);
}
.hero-grid {
  position: absolute; inset: 0; opacity: .06;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 48px 48px;
}
.hero-content {
  position: relative; z-index: 2;
  max-width: 620px;
}
.hero-badge {
  display: inline-flex; align-items: center; gap: 8px;
  background: var(--bg-card); border: 1px solid var(--border-light);
  border-radius: 99px; padding: 6px 14px; margin-bottom: 28px;
  font-size: 12px; font-weight: 600; color: var(--text-secondary);
}
.hero-badge .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px var(--green); }
.hero-title {
  font-size: clamp(38px, 6vw, 72px); font-weight: 800;
  line-height: 1.08; letter-spacing: -.03em; margin-bottom: 22px;
}
.hero-title em { font-style: normal; color: var(--accent); }
.hero-subtitle {
  font-size: 17px; color: var(--text-secondary); margin-bottom: 40px; max-width: 480px;
}
.hero-cta {
  display: flex; gap: 14px; flex-wrap: wrap;
}
.btn-primary {
  background: var(--accent); color: var(--bg-base);
  font-size: 14px; font-weight: 700; letter-spacing: .02em;
  padding: 13px 28px; border-radius: var(--radius-sm);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  display: inline-flex; align-items: center; gap: 8px;
}
.btn-primary:hover { background: #f0d78a; transform: translateY(-1px); box-shadow: 0 8px 24px rgba(232,201,122,.25); }
.btn-secondary {
  background: var(--bg-card); border: 1px solid var(--border-light);
  font-size: 14px; font-weight: 600;
  padding: 13px 28px; border-radius: var(--radius-sm);
  transition: background var(--transition), border-color var(--transition);
  display: inline-flex; align-items: center; gap: 8px;
}
.btn-secondary:hover { background: var(--bg-card-alt); border-color: var(--border-light); }

.hero-stats {
  display: flex; gap: 40px; margin-top: 56px; flex-wrap: wrap;
}
.stat-item { display: flex; flex-direction: column; }
.stat-number { font-size: 28px; font-weight: 800; color: var(--text-primary); letter-spacing: -.02em; }
.stat-label { font-size: 12px; color: var(--text-muted); margin-top: 2px; }

.hero-visual {
  position: absolute; right: 0; top: 0; bottom: 0; width: 50%;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden; pointer-events: none;
}
.hero-cards-float {
  position: relative; width: 440px; height: 480px;
}
.float-card {
  position: absolute; border-radius: var(--radius-md);
  border: 1px solid var(--border); overflow: hidden;
  box-shadow: 0 24px 64px rgba(0,0,0,.5);
  animation: floatY 6s ease-in-out infinite;
}
.float-card:nth-child(1) { width: 240px; top: 40px; left: 60px; animation-delay: 0s; }
.float-card:nth-child(2) { width: 200px; top: 160px; right: 20px; animation-delay: -2s; }
.float-card:nth-child(3) { width: 180px; bottom: 30px; left: 40px; animation-delay: -4s; }
@keyframes floatY {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-14px); }
}
.float-card-img {
  width: 100%; aspect-ratio: 4/3;
  object-fit: cover; background: var(--bg-card-alt);
  display: flex; align-items: center; justify-content: center;
  font-size: 56px;
}
.float-card-body { background: var(--bg-card); padding: 12px; }
.float-card-name { font-size: 12px; font-weight: 600; color: var(--text-primary); }
.float-card-price { font-size: 11px; color: var(--accent); margin-top: 2px; font-weight: 700; }

/* ── Marquee ── */
#marquee-bar {
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  background: var(--bg-surface);
  overflow: hidden; padding: 14px 0;
}
.marquee-track {
  display: flex; gap: 0; width: max-content;
  animation: marquee 28s linear infinite;
}
.marquee-track:hover { animation-play-state: paused; }
.marquee-item {
  display: flex; align-items: center; gap: 10px;
  padding: 0 36px; white-space: nowrap;
  font-size: 12px; font-weight: 600; letter-spacing: .05em;
  text-transform: uppercase; color: var(--text-secondary);
  border-right: 1px solid var(--border);
}
.marquee-item svg { color: var(--accent); flex-shrink: 0; }
@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

/* ── Category Strip ── */
#categories { padding: 64px 0; }
.categories-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 12px;
}
.cat-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 20px 16px;
  text-align: center; cursor: pointer;
  transition: border-color var(--transition), background var(--transition), transform var(--transition);
  display: flex; flex-direction: column; align-items: center; gap: 10px;
}
.cat-card:hover {
  border-color: var(--accent); background: var(--bg-card-alt);
  transform: translateY(-3px);
}
.cat-icon { font-size: 28px; line-height: 1; }
.cat-name { font-size: 12px; font-weight: 600; color: var(--text-secondary); }
.cat-count { font-size: 11px; color: var(--text-muted); }
.cat-card:hover .cat-name { color: var(--text-primary); }

/* ── Featured Products ── */
#featured { padding: 72px 0; }
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.product-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-md); overflow: hidden;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
  cursor: pointer; display: flex; flex-direction: column;
}
.product-card:hover {
  border-color: var(--border-light);
  transform: translateY(-4px);
  box-shadow: 0 20px 48px rgba(0,0,0,.35);
}
.product-img-wrap {
  position: relative; aspect-ratio: 1;
  background: var(--bg-card-alt);
  display: flex; align-items: center; justify-content: center;
  font-size: 72px; overflow: hidden;
}
.product-img-wrap::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(to bottom, transparent 60%, rgba(0,0,0,.3));
}
.product-badge {
  position: absolute; top: 12px; left: 12px; z-index: 2;
  font-size: 10px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  padding: 4px 10px; border-radius: 99px;
}
.badge-new { background: var(--green); color: #0a2018; }
.badge-sale { background: var(--red); color: #fff; }
.badge-hot { background: var(--accent); color: var(--bg-base); }
.product-wishlist {
  position: absolute; top: 12px; right: 12px; z-index: 2;
  width: 32px; height: 32px; border-radius: 50%;
  background: rgba(13,13,15,.7); backdrop-filter: blur(6px);
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; opacity: 0; transition: opacity var(--transition);
  border: 1px solid var(--border);
}
.product-card:hover .product-wishlist { opacity: 1; }
.product-body { padding: 16px; flex: 1; display: flex; flex-direction: column; }
.product-brand { font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: .1em; color: var(--text-muted); margin-bottom: 4px; }
.product-name { font-size: 14px; font-weight: 600; color: var(--text-primary); line-height: 1.35; margin-bottom: 8px; }
.product-rating { display: flex; align-items: center; gap: 5px; margin-bottom: 12px; }
.stars { font-size: 11px; color: var(--accent); letter-spacing: -.5px; }
.rating-count { font-size: 11px; color: var(--text-muted); }
.product-footer { margin-top: auto; display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.product-price { display: flex; align-items: baseline; gap: 7px; }
.price-current { font-size: 17px; font-weight: 800; color: var(--text-primary); }
.price-original { font-size: 13px; font-weight: 500; color: var(--text-muted); text-decoration: line-through; }
.price-pct { font-size: 11px; font-weight: 700; color: var(--green); }
.add-cart-btn {
  width: 36px; height: 36px; border-radius: var(--radius-sm);
  background: var(--accent); color: var(--bg-base);
  display: flex; align-items: center; justify-content: center;
  font-size: 16px; transition: background var(--transition), transform var(--transition);
  flex-shrink: 0;
}
.add-cart-btn:hover { background: #f0d78a; transform: scale(1.08); }

/* ── Deals ── */
#deals { padding: 72px 0; background: var(--bg-surface); }
.deals-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}
.deal-hero-card {
  grid-row: span 2;
  border-radius: var(--radius-lg); overflow: hidden;
  position: relative; min-height: 480px;
  display: flex; align-items: flex-end;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  border: 1px solid var(--border);
  transition: border-color var(--transition);
  cursor: pointer;
}
.deal-hero-card:hover { border-color: var(--border-light); }
.deal-hero-img {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 140px; opacity: .25;
}
.deal-hero-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(to top, rgba(10,10,20,.95) 30%, transparent 70%);
}
.deal-hero-content { position: relative; z-index: 2; padding: 32px; }
.deal-timer {
  display: flex; gap: 6px; margin-bottom: 16px;
}
.timer-block {
  background: rgba(232,201,122,.12); border: 1px solid rgba(232,201,122,.3);
  border-radius: var(--radius-sm); padding: 8px 10px; text-align: center; min-width: 48px;
}
.timer-num { font-size: 20px; font-weight: 800; color: var(--accent); line-height: 1; display: block; }
.timer-label { font-size: 9px; font-weight: 600; text-transform: uppercase; letter-spacing: .08em; color: var(--text-muted); }
.deal-hero-title { font-size: 26px; font-weight: 800; margin-bottom: 8px; }
.deal-hero-sub { font-size: 14px; color: var(--text-secondary); margin-bottom: 20px; }
.deal-discount-pill {
  display: inline-block; background: var(--red); color: #fff;
  font-size: 13px; font-weight: 800; padding: 4px 14px; border-radius: 99px; margin-bottom: 18px;
}

.deal-card {
  border-radius: var(--radius-md); padding: 24px;
  border: 1px solid var(--border); background: var(--bg-card);
  display: flex; gap: 20px; align-items: center;
  cursor: pointer; transition: border-color var(--transition), background var(--transition);
}
.deal-card:hover { border-color: var(--border-light); background: var(--bg-card-alt); }
.deal-card-emoji { font-size: 52px; flex-shrink: 0; }
.deal-card-info { flex: 1; min-width: 0; }
.deal-card-name { font-size: 15px; font-weight: 700; margin-bottom: 4px; }
.deal-card-sub { font-size: 12px; color: var(--text-secondary); margin-bottom: 12px; }
.deal-price-row { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; }
.deal-current { font-size: 20px; font-weight: 800; }
.deal-original { font-size: 13px; color: var(--text-muted); text-decoration: line-through; }
.deal-save { font-size: 11px; font-weight: 700; color: var(--green); }
.deal-bar-wrap { background: var(--bg-base); border-radius: 99px; height: 5px; overflow: hidden; }
.deal-bar { height: 100%; border-radius: 99px; background: linear-gradient(90deg, var(--accent-dim), var(--accent)); }
.deal-bar-label { font-size: 10px; color: var(--text-muted); margin-top: 4px; }

/* ── Editorial / Collections ── */
#editorial { padding: 72px 0; }
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.editorial-card {
  border-radius: var(--radius-lg); overflow: hidden;
  position: relative; min-height: 360px;
  display: flex; flex-direction: column; justify-content: flex-end;
  cursor: pointer; border: 1px solid var(--border);
  transition: border-color var(--transition), transform var(--transition);
}
.editorial-card:hover { border-color: var(--border-light); transform: translateY(-4px); }
.editorial-bg {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 100px; opacity: .2;
}
.editorial-gradient { position: absolute; inset: 0; }
.editorial-content { position: relative; z-index: 2; padding: 28px; }
.editorial-tag {
  display: inline-block; font-size: 10px; font-weight: 700;
  text-transform: uppercase; letter-spacing: .1em;
  padding: 4px 12px; border-radius: 99px; margin-bottom: 12px;
  border: 1px solid;
}
.editorial-title { font-size: 20px; font-weight: 800; margin-bottom: 8px; line-height: 1.25; }
.editorial-sub { font-size: 13px; color: rgba(255,255,255,.65); margin-bottom: 18px; }
.editorial-link {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 13px; font-weight: 600;
  transition: gap var(--transition);
}
.editorial-card:hover .editorial-link { gap: 10px; }

/* ── Trending ── */
#trending { padding: 72px 0; background: var(--bg-surface); }
.trending-list {
  display: flex; flex-direction: column; gap: 2px;
}
.trending-row {
  display: grid;
  grid-template-columns: 48px 1fr auto;
  align-items: center; gap: 20px;
  padding: 16px 20px; border-radius: var(--radius-md);
  border: 1px solid transparent;
  transition: background var(--transition), border-color var(--transition);
  cursor: pointer;
}
.trending-row:hover { background: var(--bg-card); border-color: var(--border); }
.trend-rank { font-size: 22px; font-weight: 800; color: var(--text-muted); text-align: center; }
.trend-rank.top { color: var(--accent); }
.trend-info { display: flex; align-items: center; gap: 16px; }
.trend-emoji { font-size: 36px; flex-shrink: 0; }
.trend-name { font-size: 15px; font-weight: 600; }
.trend-cat { font-size: 12px; color: var(--text-muted); margin-top: 2px; }
.trend-right { display: flex; align-items: center; gap: 24px; text-align: right; }
.trend-price { font-size: 15px; font-weight: 700; }
.trend-change { font-size: 12px; font-weight: 600; padding: 3px 10px; border-radius: 99px; white-space: nowrap; }
.up { color: var(--green); background: rgba(82,217,138,.1); }
.down { color: var(--red); background: rgba(224,82,82,.1); }

/* ── Newsletter ── */
#newsletter { padding: 80px 0; }
.newsletter-box {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 60px;
  text-align: center; position: relative; overflow: hidden;
}
.newsletter-box::before {
  content: ''; position: absolute;
  inset: -1px; border-radius: inherit;
  background: linear-gradient(135deg, rgba(232,201,122,.15), transparent 50%, rgba(82,217,138,.08));
  pointer-events: none;
}
.newsletter-glow {
  position: absolute; top: -80px; left: 50%; transform: translateX(-50%);
  width: 400px; height: 200px;
  background: radial-gradient(ellipse, rgba(232,201,122,.12), transparent 70%);
  pointer-events: none;
}
.newsletter-title { font-size: clamp(22px, 3vw, 34px); font-weight: 800; margin-bottom: 12px; }
.newsletter-sub { font-size: 16px; color: var(--text-secondary); margin-bottom: 36px; max-width: 480px; margin-left: auto; margin-right: auto; }
.newsletter-form { display: flex; gap: 10px; max-width: 480px; margin: 0 auto; }
.newsletter-input {
  flex: 1; background: var(--bg-base); border: 1px solid var(--border-light);
  border-radius: var(--radius-sm); padding: 13px 18px;
  color: var(--text-primary); font-size: 14px; outline: none;
  transition: border-color var(--transition);
}
.newsletter-input:focus { border-color: var(--accent); }
.newsletter-input::placeholder { color: var(--text-muted); }
.newsletter-perks { display: flex; justify-content: center; gap: 28px; margin-top: 24px; flex-wrap: wrap; }
.perk { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--text-muted); }
.perk svg { color: var(--green); }

/* ── Footer ── */
#footer {
  border-top: 1px solid var(--border);
  padding: 64px 0 32px; background: var(--bg-surface);
}
.footer-top {
  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 48px; margin-bottom: 48px;
}
.footer-brand-name { font-size: 22px; font-weight: 800; letter-spacing: -.03em; margin-bottom: 14px; }
.footer-brand-name span { color: var(--accent); }
.footer-tagline { font-size: 13px; color: var(--text-muted); line-height: 1.7; max-width: 240px; margin-bottom: 24px; }
.footer-socials { display: flex; gap: 8px; }
.social-btn {
  width: 34px; height: 34px; border-radius: var(--radius-sm);
  background: var(--bg-card); border: 1px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; color: var(--text-muted);
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.social-btn:hover { color: var(--text-primary); border-color: var(--border-light); background: var(--bg-card-alt); }
.footer-col-title { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: var(--text-primary); margin-bottom: 16px; }
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-links a { font-size: 13px; color: var(--text-muted); transition: color var(--transition); }
.footer-links a:hover { color: var(--text-primary); }
.footer-bottom {
  border-top: 1px solid var(--border); padding-top: 28px;
  display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;
}
.footer-copy { font-size: 12px; color: var(--text-muted); }
.footer-payments { display: flex; gap: 8px; align-items: center; }
.payment-badge {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: 4px; padding: 4px 10px;
  font-size: 10px; font-weight: 700; color: var(--text-muted); letter-spacing: .03em;
}

/* ── Toast ── */
#toast-container { position: fixed; bottom: 24px; right: 24px; z-index: 999; display: flex; flex-direction: column; gap: 10px; }
.toast {
  background: var(--bg-card); border: 1px solid var(--border-light);
  border-radius: var(--radius-md); padding: 14px 18px;
  display: flex; align-items: center; gap: 12px;
  font-size: 14px; min-width: 260px;
  box-shadow: 0 12px 40px rgba(0,0,0,.4);
  animation: slideUp .3s ease forwards;
}
@keyframes slideUp {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}
.toast-icon { font-size: 18px; flex-shrink: 0; }

/* ── Responsive ── */
@media (max-width: 1100px) {
  .products-grid { grid-template-columns: repeat(3, 1fr); }
  .categories-grid { grid-template-columns: repeat(4, 1fr); }
  .footer-top { grid-template-columns: 1fr 1fr 1fr; }
}
@media (max-width: 860px) {
  .hero-visual { display: none; }
  #hero { min-height: auto; padding: 80px 0; }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-layout { grid-template-columns: 1fr; }
  .deal-hero-card { grid-row: span 1; min-height: 320px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .nav-links { display: none; }
  .nav-search { display: none; }
  .footer-top { grid-template-columns: 1fr 1fr; }
  .trending-row { grid-template-columns: 40px 1fr; }
  .trend-right { display: none; }
}
@media (max-width: 540px) {
  .products-grid { grid-template-columns: 1fr; }
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: 1fr; }
  .newsletter-form { flex-direction: column; }
  .newsletter-box { padding: 36px 24px; }
  .hero-stats { gap: 24px; }
  .footer-top { grid-template-columns: 1fr 1fr; }
}

data.permission_request:
