+}
+.newsletter-title { font-size: clamp(22px, 3vw, 34px); font-weight: 800; margin-bottom: 12px; }
+.newsletter-sub { font-size: 16px; color: var(--text-secondary); margin-bottom: 36px; max-width: 480px; margin-left: auto; margin-right: auto; }
+.newsletter-form { display: flex; gap: 10px; max-width: 480px; margin: 0 auto; }
+.newsletter-input {
+  flex: 1; background: var(--bg-base); border: 1px solid var(--border-light);
+  border-radius: var(--radius-sm); padding: 13px 18px;
+  color: var(--text-primary); font-size: 14px; outline: none;
+  transition: border-color var(--transition);
+}
+.newsletter-input:focus { border-color: var(--accent); }
+.newsletter-input::placeholder { color: var(--text-muted); }
+.newsletter-perks { display: flex; justify-content: center; gap: 28px; margin-top: 24px; flex-wrap: wrap; }
+.perk { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--text-muted); }
+.perk svg { color: var(--green); }
+
+/* ── Footer ── */
+#footer {
+  border-top: 1px solid var(--border);
+  padding: 64px 0 32px; background: var(--bg-surface);
+}
+.footer-top {
+  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 48px; margin-bottom: 48px;
+}
+.footer-brand-name { font-size: 22px; font-weight: 800; letter-spacing: -.03em; margin-bottom: 14px; }
+.footer-brand-name span { color: var(--accent); }
+.footer-tagline { font-size: 13px; color: var(--text-muted); line-height: 1.7; max-width: 240px; margin-bottom: 24px; }
+.footer-socials { display: flex; gap: 8px; }
+.social-btn {
