          <ul class="footer-links">${col.links.map(l => `<li><a href="#">${l}</a></li>`).join('')}</ul>
        </div>`).join('')}
      </div>
      <div class="footer-bottom">
        <p class="footer-copy">© 2026 LuxEra Inc. All rights reserved.</p>
        <div class="footer-payments">
          <span class="payment-badge">VISA</span>
          <span class="payment-badge">MC</span>
          <span class="payment-badge">AMEX</span>
          <span class="payment-badge">PAYPAL</span>
          <span class="payment-badge">APPLE PAY</span>
        </div>
      </div>
    </div>
  </footer>`;
}

/* ── Mount ── */
function render() {
  document.getElementById('app').innerHTML = [
    Navbar(), Hero(), MarqueeBar(), Categories(),
    FeaturedProducts(), DealsSection(), Editorial(),
    Trending(), Newsletter(), Footer(),
    `<div id="toast-container"></div>`,
  ].join('');

  /* Add-to-cart buttons */
  document.querySelectorAll('.add-cart-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const p = PRODUCTS.find(p => p.id === +btn.dataset.id);
      if (p) addToCart(p);
    });
  });

  /* Deal card quick-add */
  document.querySelectorAll('.deal-card').forEach((card, i) => {
    card.addEventListener('click', () => addToCart([PRODUCTS[2], PRODUCTS[6]][i]));
  });

  /* Newsletter */
  window.handleSubscribe = (e) => {
    e.preventDefault();
    showToast('🎉 <strong>You\'re subscribed!</strong> Check your inbox.');
    e.target.reset();
  };

  startCountdown();
}

/* ── Countdown ── */
function startCountdown() {
  let h = 7, m = 34, s = 52;
  const th = document.getElementById('t-h');
  const tm = document.getElementById('t-m');
  const ts = document.getElementById('t-s');
  if (!th) return;
  setInterval(() => {
    s--;
    if (s < 0) { s = 59; m--; }
    if (m < 0) { m = 59; h--; }
    if (h < 0) { h = 0; m = 0; s = 0; }
    th.textContent = String(h).padStart(2,'0');
    tm.textContent = String(m).padStart(2,'0');
    ts.textContent = String(s).padStart(2,'0');
  }, 1000);
}

